import csv
from typing import List, Dict, Any

def parse_csv(raw_csv: str) -> Dict[str, Any]:
    """
    Parses a raw CSV string into a dictionary with columns and rows.

    Parameters:
    raw_csv (str): The complete raw file content

    Returns:
    Dict[str, Any]: Dictionary containing 'columns' and 'rows' lists of strings
    """
    # Initialize data structures
    columns = []
    rows = []

    # Split by delimiter
    lines = raw_csv.split('\n')

    if not lines:
        return {"columns": [], "rows": []}

    # Handle preambles (lines before the first actual row)
    header_line = None
    for line in lines:
        if line.strip() and not line.startswith('"'):
            header_line = line
            break

    if not header_line:
        return {"columns": [], "rows": []}

    # Parse headers
    try:
        header_data = parse_header(header_line)
        columns = [row.strip() for row in header_data]
    except Exception as e:
        return {"columns": [], "rows": []}

    # Process remaining lines
    for line in lines[1:]:
        if not line.strip():
            continue

        try:
            row_data = parse_row(line)
            rows.append(row_data)
        except Exception as e:
            return {"columns": [], "rows": []}

    # Convert to list of lists for JSON serialization
    result = {
        "columns": columns,
        "rows": rows
    }

    return result

def parse_header(line: str) -> List[str]:
    """
    Parses a single header line into a list of column names.
    Handles quoted headers and escaped quotes.
    """
    if not line.strip():
        return []

    # Split by comma, but handle quoted fields
    parts = []
    current_field = ""
    in_quotes = False

    for char in line:
        if char == '"':
            in_quotes = not in_quotes
            current_field += char
        elif char == ',' and not in_quotes:
            parts.append(current_field.strip())
            current_field = ""
        else:
            current_field += char

    # Add the last field
    parts.append(current_field.strip())

    return parts

def parse_row(line: str) -> List[str]:
    """
    Parses a single row line into a list of column values.
    Handles quoted rows, escaped quotes, and multi-line headers.
    """
    if not line.strip():
        return []

    # Split by delimiter
    parts = line.split(',')

    # Handle multi-line headers (lines starting with ' or ending with ')
    header_parts = []
    current_header = ""
    in_quotes = False

    for part in parts:
        if not part.strip():
            continue

        if part.startswith('"') and part.endswith('"'):
            # Check if this is a multi-line header
            if current_header and current_header.strip() != "":
                header_parts.append(current_header)
                current_header = ""
            in_quotes = True
            current_header = part[1:-1]  # Remove quotes
        elif not in_quotes:
            current_header += part
        else:
            # Quoted field, append to previous header if exists
            if current_header and current_header.strip():
                header_parts.append(current_header)
                current_header = ""
            current_header = part

    # Add the last header
    if current_header and current_header.strip():
        header_parts.append(current_header)

    return [row.strip() for row in header_parts]

